import fs from "node:fs";
import path from "node:path";
import Database from "better-sqlite3";

const FILE = path.resolve("data/waterlog.db");

fs.mkdirSync(path.dirname(FILE), { recursive: true });
const db = new Database(FILE);
db.pragma("journal_mode = WAL");
db.exec(`CREATE TABLE IF NOT EXISTS plants (
  name TEXT PRIMARY KEY,
  last_watered TEXT NOT NULL,
  by TEXT
)`);

const selectAll = db.prepare("SELECT name, last_watered, by FROM plants");
const upsert = db.prepare(
  `INSERT INTO plants (name, last_watered, by) VALUES (@name, @at, @by)
   ON CONFLICT(name) DO UPDATE SET last_watered = excluded.last_watered, by = excluded.by`,
);

export function load() {
  const plants = {};
  for (const row of selectAll.all()) plants[row.name] = { lastWatered: row.last_watered, by: row.by };
  return { plants };
}

export function recordWatering(name, by, at = new Date()) {
  const entry = { name, by, at: at.toISOString() };
  upsert.run({ name: entry.name, by: entry.by ?? null, at: entry.at });
  return entry;
}

