11	const server = http.createServer((req, res) => {
12	  const url = new URL(req.url, "http://localhost");
13	  if (req.method === "GET" && url.pathname === "/plants") return send(res, 200, load().plants);
14	  const m = /^\/plants\/([^/]+)\/water$/.exec(url.pathname);
15	  if (req.method === "POST" && m) {
16	    let body = "";
17	    req.on("data", (c) => (body += c));
18	    req.on("end", () => {
19	      try {
20	        const { by } = JSON.parse(body || "{}");
21	        const name = decodeURIComponent(m[1]);
22	        console.log(`watering ${name} by ${by}`);
23	        send(res, 200, recordWatering(name, by));
24	      } catch (err) {
25	        console.error(err);
26	        send(res, 500, { error: "internal error" });
27	      }
28	    });
29	    return;
30	  }
31	  send(res, 404, { error: "not found" });
32	});
